code.cpp:
class Solution {
public:
    string orderlyQueue(string s, int k) {
        if (k == 1) {
            string best = s;
            int n = s.size();
            for (int i = 1; i < n; i++) {
                string rot = s.substr(i) + s.substr(0, i);
                if (rot < best) best = rot;
            }
            return best;
        } else {
            sort(s.begin(), s.end());
            return s;
        }
    }
};
